def stoneGameIII(stoneValue):
    n = len(stoneValue)
    dp = [float('-inf')] * (n+1)
    dp[n] = 0  # Base: no stones left
    for i in range(n-1, -1, -1):
        total = 0
        for k in range(1, 4):
            if i + k <= n:
                total += stoneValue[i + k - 1]
                dp[i] = max(dp[i], total - dp[i+k])
    if dp[0] > 0:
        return 'Alice'
    if dp[0] < 0:
        return 'Bob'
    return 'Tie'
